import {projectAtoms,particleColours} from './model-geometry.js?v=20261023-physicscomplete01';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function moleculeDiagram(m){const xy=projectAtoms(m.atoms);const lines=m.bonds.map(([a,b])=>`<path data-bond="${a}-${b}" d="M${xy[a].join(' ')}L${xy[b].join(' ')}" stroke="#d4dfe7" stroke-width="5" stroke-linecap="round"/>`).join('');const atoms=m.atoms.map(([el],i)=>`<circle cx="${xy[i][0]}" cy="${xy[i][1]}" r="20" fill="${particleColours[el]||'#b7c8d6'}" stroke="#d4dfe7" stroke-width="1.5"/><text x="${xy[i][0]}" y="${xy[i][1]+5}" text-anchor="middle" fill="#182e44" font-family="sans-serif" font-size="14">${escape(el)}</text>`).join('');const counts=Object.entries(m.atoms.reduce((a,[el])=>(a[el]=(a[el]||0)+1,a),{})).map(([el,n])=>`${n} ${el}`).join(', ');return `<svg class="lab-svg" viewBox="0 0 440 260" role="img" aria-label="${escape(m.name)}: ${counts||'no atoms placed'}. ${m.bonds.length} displayed connections. Projected schematic; positions and sizes are symbolic.">${lines}${atoms}<text x="220" y="247" text-anchor="middle" fill="#d4dfe7" font-family="sans-serif" font-size="11">${m.atoms.length?'Connections preserved · projection, not a structural formula':'Add atoms to begin your model'}</text></svg>`;}
export const svg=(body,label)=>`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="${escape(label)}">${body}</svg>`;
export const label=(x,y,s,size=13)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#d4dfe7" font-family="sans-serif" font-size="${size}">${escape(s)}</text>`;
export function nobleDiagram(selected){const values=[['He',-269],['Ne',-246],['Ar',-186]],y=v=>225-(v+300)*1.15;let art='';for(const v of[-300,-250,-200,-150])art+=`<path d="M65 ${y(v)}H405" stroke="#b7c8d6" stroke-opacity=".25"/>`+label(35,y(v)+4,v,11);values.forEach(([el,v],i)=>{const x=95+i*110;art+=`<rect x="${x}" y="${y(v)}" width="58" height="${225-y(v)}" rx="4" fill="${selected===el?'#d4dfe7':'#304b61'}"/>`+label(x+29,y(v)-10,v+' °C',12)+label(x+29,250,el,13);});art+=label(220,23,'Boiling point / °C',15)+label(220,278,'Axis begins at −300 °C · approximate values',10);return svg(art,'Noble gas boiling points: helium −269, neon −246, argon −186 degrees Celsius. Linear axis starts at −300 degrees.');}
export function massBoundaryDiagram(t,reveal){const mode=t?.reason||'enter',enter=mode==='enter',closed=mode==='closed';let art=`<rect x="90" y="65" width="260" height="130" rx="16" fill="#304b61" fill-opacity=".45" stroke="#b7c8d6" stroke-width="2" stroke-dasharray="6 5"/>`+label(220,40,'WEIGHED BOUNDARY',12)+label(220,105,closed?'Whole system':enter?'Magnesium sample':'Solid sample',16)+label(220,140,closed?(t?.before||'60.0 g whole system'):enter?'Initially 2.4 g Mg':'Initially 10.0 g CaCO₃',12);if(!closed)art+=`<path d="${enter?'M30 170H145':'M295 170H410'}" stroke="#f0b4a6" stroke-width="3"/><path d="${enter?'M135 164l10 6l-10 6':'M400 164l10 6l-10 6'}" fill="none" stroke="#f0b4a6" stroke-width="3"/>`+label(220,218,enter?'O₂ enters → solid sample gains mass':'CO₂ leaves → solid sample loses mass',12);else art+=label(220,218,'No material crosses the boundary',12);art+=label(220,263,reveal?t.after:'Predict the mass, then check to reveal',12);return svg(art,`${t?.name||'Oxygen entering'}. Dashed line is the weighed boundary. ${closed?'All material stays inside':enter?'Oxygen enters the solid sample':'Carbon dioxide leaves the solid sample'}. ${reveal?t.after:'Mass outcome hidden until checked'}. Bookkeeping schematic, not apparatus.`);}
export function buretteDiagram(t,reveal,result){const initial=t?.initial??.2,final=t?.final??24.3;let art='';[[135,initial,'Initial'],[305,final,'Final']].forEach(([x,v,name])=>{const y=53+v*3;art+=`<rect x="${x-14}" y="50" width="28" height="155" rx="7" fill="#b7c8d6" fill-opacity=".13" stroke="#d4dfe7"/><rect x="${x-11}" y="${y}" width="22" height="${203-y}" fill="#b7c8d6" fill-opacity=".65"/><path d="M${x-12} ${y}Q${x} ${y+4} ${x+12} ${y}" stroke="#d4dfe7" fill="none" stroke-width="2"/>`;for(let n=0;n<=50;n+=10)art+=`<path d="M${x+15} ${53+n*3}h8" stroke="#d4dfe7"/>`+label(x+38,57+n*3,n,10);art+=label(x,30,name,13)+label(x,231,v.toFixed(2)+' cm³',14);});art+=label(220,268,reveal?`Delivered ${Number(result.titre.toFixed(3))} cm³ · mean ${Number(result.mean.toFixed(3))} cm³`:'Reading increases downwards · titre = final − initial',11);return svg(art,`Supplied burette readings: initial ${initial.toFixed(2)}, final ${final.toFixed(2)} cubic centimetres. Scale increases downwards from 0 to 50. ${reveal?'Delivered '+result.titre+' cubic centimetres.':'Predict delivered volume before reveal.'} Schematic, not a precision reading exercise.`);}
